import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type RadarScannerProps = Record<string, any>;

const RadarScanner: React.FC<RadarScannerProps> = ({
  backgroundColor = "#08080a",
  transparentBackground = false,
  durationInSeconds = 10,
  radarColors = ["#FDFBF7", "#F2E3D5", "#E6C29B", "#C88550"],
  clientLabel = "CLIENT GLOW LEVEL:",
  resultText = "COMPLETE GLOW GIRL",
  glowIntensity = 1.0,
  particleCount = 30,
  scanSpeedSeconds = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const minSize = Math.min(width, height);
  const radarOuterSize = minSize * 0.8;
  const radarInnerSize = radarOuterSize * 0.7;
  const strokeWidth = (radarOuterSize - radarInnerSize) / 2;

  // Motion calculations
  const framesPerRotation = fps * scanSpeedSeconds;
  const rotationAngle = (frame / framesPerRotation) * 360;

  // Determine when the scanner hits the bronze area (roughly 240deg to 360deg)
  const currentRotationMod = rotationAngle % 360;
  const bronzeGlowPhase = interpolate(
    currentRotationMod,
    [200, 270, 340, 360],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Text Animation timings based on first full rotation
  const textRevealFrame = framesPerRotation * 0.85; // Reveal near the end of the first bronze pass
  
  const labelOpacity = interpolate(frame, [15, 45], [0, 1], { extrapolateRight: "clamp" });
  
  const resultScale = spring({
    frame: frame - textRevealFrame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  const resultOpacity = interpolate(
    frame,
    [textRevealFrame, textRevealFrame + 15],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Generate deterministic particles
  const particles = React.useMemo(() => {
    return Array.from({ length: particleCount }).map((_, i) => {
      return {
        id: i,
        xBase: random(`px_${i}`),
        yBase: random(`py_${i}`),
        speed: 0.5 + random(`ps_${i}`) * 1.5,
        size: 2 + random(`pz_${i}`) * 6,
        opacity: 0.1 + random(`po_${i}`) * 0.4,
      };
    });
  }, [particleCount]);

  // Construct the CSS conic gradient string for the base spectrum
  const colorStops = radarColors
    .map((c, i) => `${c} ${(i / (radarColors.length - 1)) * 100}%`)
    .join(", ");
  const baseGradient = `conic-gradient(from 0deg, ${colorStops})`;

  // Sweep gradient (transparent tail leading to a bright white/amber edge)
  const sweepGradient = `conic-gradient(from 0deg, transparent 0%, transparent 70%, rgba(200, 133, 80, 0.2) 90%, rgba(253, 251, 247, 0.9) 99%, #FFFFFF 100%)`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      
      {/* Background Particles */}
      <AbsoluteFill style={{ transition: "none" }}>
        {particles.map((p) => {
          // Drift upwards continuously
          const driftY = (frame * p.speed) % height;
          const currentY = height - driftY;
          // Slight sine wave wobble on X
          const currentX = p.xBase * width + Math.sin(frame * 0.02 + p.id) * 20;

          return (
            <div
              key={p.id}
              style={{
                position: "absolute",
                left: currentX,
                top: currentY,
                width: p.size,
                height: p.size,
                backgroundColor: "#E6C29B",
                borderRadius: "50%",
                opacity: p.opacity,
                filter: "blur(2px)",
                transition: "none",
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* Main Radar Container */}
      <div
        style={{
          position: "absolute",
          top: height * 0.4 - radarOuterSize / 2,
          left: width * 0.5 - radarOuterSize / 2,
          width: radarOuterSize,
          height: radarOuterSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Deep Bronze Intense Back-Glow (Pulsing) */}
        <div
          style={{
            position: "absolute",
            top: "-10%",
            left: "-10%",
            width: "120%",
            height: "120%",
            borderRadius: "50%",
            background: "radial-gradient(circle, rgba(200,133,80,0.6) 0%, transparent 70%)",
            opacity: bronzeGlowPhase * glowIntensity,
            filter: "blur(40px)",
            transform: `scale(${1 + bronzeGlowPhase * 0.1})`,
            transition: "none",
          }}
        />

        {/* Outer Ring Spectrum Masked Area */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            background: baseGradient,
            boxShadow: "0 0 30px rgba(0,0,0,0.8) inset, 0 0 20px rgba(255,255,255,0.05)",
            transition: "none",
            maskImage: `radial-gradient(transparent ${radarInnerSize/2}px, black ${radarInnerSize/2 + 2}px)`,
            WebkitMaskImage: `radial-gradient(transparent ${radarInnerSize/2}px, black ${radarInnerSize/2 + 2}px)`,
          }}
        >
          {/* Subtle noise/texture over the spectrum could go here, omitting for clean glass look */}
        </div>

        {/* Scanning Sweep */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            background: sweepGradient,
            transform: `rotate(${rotationAngle}deg)`,
            transformOrigin: "center center",
            transition: "none",
            maskImage: `radial-gradient(transparent ${radarInnerSize/2}px, black ${radarInnerSize/2 + 2}px)`,
            WebkitMaskImage: `radial-gradient(transparent ${radarInnerSize/2}px, black ${radarInnerSize/2 + 2}px)`,
          }}
        >
          {/* Leading Edge Bright Line */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: "49.5%",
              width: "1%",
              height: "50%",
              background: "#FFFFFF",
              boxShadow: "0 0 15px 5px rgba(255, 255, 255, 0.8)",
              transition: "none",
            }}
          />
        </div>

        {/* Inner Tech Grid (SVG) */}
        <div
          style={{
            position: "absolute",
            width: radarInnerSize,
            height: radarInnerSize,
            borderRadius: "50%",
            backgroundColor: "rgba(0,0,0,0.4)",
            boxShadow: "inset 0 0 40px rgba(0,0,0,0.8)",
            transition: "none",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <svg width="100%" height="100%" style={{ opacity: 0.3, transition: "none" }}>
            <circle cx="50%" cy="50%" r="20%" stroke="#FFFFFF" strokeWidth="1" fill="none" />
            <circle cx="50%" cy="50%" r="40%" stroke="#FFFFFF" strokeWidth="1" strokeDasharray="4 4" fill="none" />
            <line x1="50%" y1="10%" x2="50%" y2="90%" stroke="#FFFFFF" strokeWidth="1" />
            <line x1="10%" y1="50%" x2="90%" y2="50%" stroke="#FFFFFF" strokeWidth="1" />
            
            {/* Center Blip */}
            <circle 
              cx="50%" 
              cy="50%" 
              r="2%" 
              fill="#FFFFFF" 
              style={{
                opacity: 0.5 + Math.sin(frame * 0.1) * 0.5,
                transition: "none"
              }} 
            />
          </svg>
        </div>
      </div>

      {/* Glassmorphism UI Panel */}
      <div
        style={{
          position: "absolute",
          top: height * 0.7,
          width: width * 0.86,
          left: width * 0.07,
          padding: "50px 40px",
          background: "rgba(255, 255, 255, 0.04)",
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          borderRadius: "32px",
          border: "1px solid rgba(255, 255, 255, 0.08)",
          boxShadow: "0 20px 50px rgba(0,0,0,0.5), inset 0 0 0 1px rgba(255,255,255,0.02)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily: spaceGroteskFamily,
            fontSize: "28px",
            color: "rgba(255, 255, 255, 0.6)",
            letterSpacing: "0.2em",
            marginBottom: "24px",
            opacity: labelOpacity,
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {clientLabel}
        </div>

        <div
          style={{
            fontFamily: montserratFamily,
            fontSize: "56px",
            fontWeight: 300,
            color: "#FDFBF7",
            textAlign: "center",
            lineHeight: 1.2,
            opacity: resultOpacity,
            transform: `scale(${resultScale}) translateY(${(1 - resultScale) * 20}px)`,
            textShadow: `0 0 ${20 * bronzeGlowPhase * glowIntensity}px rgba(200, 133, 80, 0.8)`,
            transition: "none",
          }}
        >
          {resultText}
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default RadarScanner;